WITH base AS (SELECT user_cohort_activity.cohort_week AS `cohortWeek`, user_cohort_activity.weeks_since_signup AS `weeksSinceSignup`, MAX(user_cohort_activity.cohort_size) AS `cohortSize`, COUNT(DISTINCT user_cohort_activity.user_id) AS `activeUsers` FROM user_cohort_activity WHERE toDateTime64(user_cohort_activity.cohort_week, 9, 'UTC') BETWEEN ? AND ? AND user_cohort_activity.weeks_since_signup <= ? GROUP BY `cohortWeek`, `weeksSinceSignup`) SELECT `cohortWeek`, `weeksSinceSignup`, `cohortSize`, `activeUsers`, (toFloat64(`activeUsers`) / NULLIF(`cohortSize`, 0)) AS `retention` FROM base ORDER BY `cohortWeek` ASC, `weeksSinceSignup` ASC
